#include <stdio.h>

int square(int n);           /* 声明：定义在后面，所以必须先声明 */

int main(void) {
    int i;
    for (i = 1; i <= 3; i++) {
        printf("%d*%d=%d\n", i, i, square(i));   /* 嵌套调用 */
    }
    return 0;
}

int square(int n) {          /* 定义：与 main 并列，不嵌套 */
    return n * n;
}

#include <stdio.h>

int main(void) {
    int a = 3, b = 5;        /* 声明语句 */

    a = a + b;               /* 表达式语句 */
    printf("a=%d\n", a);     /* 函数调用语句 */

    if (a > 7) {             /* 控制语句 + 复合语句，} 后不加分号 */
        printf("big\n");
    } else {
        printf("small\n");
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    int Sum = 1;         /* 合法：首字符是字母，与 sum 不是同一个名字 */
    int sum = 2;         /* 合法 */
    int _total = 3;      /* 合法：下划线开头 */
    int a1_b2 = 4;       /* 合法：数字出现在中间 */

    /* 非法（不能写）：2sum  a-b  a.b  my name  int */
    printf("%d %d %d %d\n", Sum, sum, _total, a1_b2);
    return 0;
}

#include <stdio.h>

int main(void) {
    int a = 10;               /* 定义变量并初始化 */
    const int LIMIT = 20;     /* 符号常量：只读 */

    printf("a=%d LIMIT=%d\n", a, LIMIT);
    a = a + 5;                /* 变量的值可以改写 */
    printf("a=%d\n", a);
    /* LIMIT = 30;  若取消注释会编译报错：assignment of read-only variable */
    return 0;
}

#include <stdio.h>
#define PI 3.14159      /* 预处理阶段 PI 被原样替换成 3.14159 */

int main(void) {
    double r = 2.0;
    printf("area=%g\n", PI * r * r);
    return 0;
}

#include <stdio.h>

int main(void) {
    int i, sum = 0;              /* 顺序结构 */

    for (i = 1; i <= 5; i++) {   /* 循环结构 */
        if (i % 2 == 0) {        /* 选择结构 */
            continue;
        }
        sum = sum + i;           /* 顺序结构 */
    }
    printf("sum=%d\n", sum);
    return 0;
}

#include <stdio.h>

/* 伪代码：
   sum = 0, i = 1
   当 i <= 100 时反复执行：sum = sum + i；i = i + 1
   输出 sum                                              */
int main(void) {
    int sum = 0, i = 1;
    while (i <= 100) {
        sum = sum + i;
        i = i + 1;
    }
    printf("sum=%d\n", sum);
    return 0;
}

#include <stdio.h>

/* 模块：读入 n 个成绩并返回总分 */
int read_sum(int n);

int main(void) {
    int n = 4;
    int sum = read_sum(n);                    /* 调用求和模块 */
    printf("avg=%.2f\n", (double)sum / n);   /* 求平均并输出 */
    return 0;
}

int read_sum(int n) {
    int i, x, sum = 0;
    for (i = 1; i <= n; i++) {
        scanf("%d", &x);      /* 2.2 每次读一个成绩 */
        sum = sum + x;         /* 2.3 累加 */
    }
    return sum;
}

#include <stdio.h>
#include <math.h>          /* 用 sqrt 必须包含它 */

int main(void) {
    int r;
    scanf("%d", &r);                       /* 输入：库函数 scanf */
    printf("r=%d\n", r);                   /* 输出：库函数 printf */
    printf("sqrt=%g\n", sqrt((double)r));  /* 数学库函数 */
    return 0;
}
